/**
 * aiGlossary.js
 * ---------------------------------------------------------------------------
 * Business logic for the AI Glossary (ai_glossary collection).
 *
 * Exports:
 *   - seedAiGlossary({ force })
 *   - getAiGlossary({ language })
 *   - getAiGlossaryTerm(slug)
 *
 * Docs are keyed by slug. English copy is hardcoded in GLOSSARY_TERMS;
 * Hebrew copy is generated by Gemini at seed time (one batched call per
 * term, bounded concurrency, exponential backoff).
 */

const admin = require('firebase-admin');
const { db, logger } = require('./config');
const { loadGeminiSDK, getGeminiSDK } = require('./utils');

const COLL = 'ai_glossary';
const MODEL = 'gemini-2.5-flash';

const CATEGORY_ORDER = { core: 0, models: 1, agents: 2, developer: 3 };

function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

async function getGenAI() {
  if (!process.env.GEMINI_API_KEY) throw new Error('GEMINI_API_KEY is not set');
  await loadGeminiSDK();
  const { GoogleGenAI } = getGeminiSDK();
  if (!GoogleGenAI) throw new Error('Gemini SDK failed to load');
  return new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
}

async function pMap(items, mapper, concurrency = 4) {
  const results = new Array(items.length);
  let idx = 0;
  const workers = new Array(Math.min(concurrency, items.length)).fill(0).map(async () => {
    for (;;) {
      const i = idx++;
      if (i >= items.length) return;
      try { results[i] = { ok: true, value: await mapper(items[i], i) }; }
      catch (err) { results[i] = { ok: false, error: err }; }
    }
  });
  await Promise.all(workers);
  return results;
}

function parseJsonLoose(text) {
  if (!text) return null;
  let s = String(text).trim();
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  const first = s.indexOf('{');
  const last = s.lastIndexOf('}');
  if (first !== -1 && last !== -1 && last > first) s = s.slice(first, last + 1);
  try { return JSON.parse(s); } catch (_) { return null; }
}

function isRetryable(err) {
  const msg = String(err && err.message || '');
  if (/429|rate.?limit|RESOURCE_EXHAUSTED|quota/i.test(msg)) return true;
  if (/5\d\d|UNAVAILABLE|INTERNAL|DEADLINE_EXCEEDED|ECONNRESET|ETIMEDOUT/i.test(msg)) return true;
  return false;
}

