function buildHePrompt(term_en, definition_en) {
  return `Translate this AI/tech glossary entry to Hebrew. Return JSON with EXACTLY these keys:
- term_he: the term in natural Hebrew (keep widely-used English acronyms like LLM, MCP, RAG, LoRA, AGI as-is; can add parenthetical Hebrew explanation)
- definition_he: a natural Hebrew translation (NOT literal) of the definition, same length and tone, plain language, no markdown, no emoji

ENGLISH TERM: ${term_en}
ENGLISH DEFINITION: ${definition_en}

Output ONLY the JSON object. No commentary, no code fences.`;
}

async function translateOne(genAI, term, maxRetries = 4) {
  const prompt = buildHePrompt(term.term_en, term.definition_en);
  let lastErr;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const res = await genAI.models.generateContent({
        model: MODEL,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: { temperature: 0.4, responseMimeType: 'application/json' },
      });
      const text = (res && (res.text || (res.response && res.response.text && res.response.text()))) || '';
      const parsed = parseJsonLoose(text);
      if (!parsed) throw new Error('aiGlossary: failed to parse JSON');
      const term_he = String(parsed.term_he || '').trim();
      const definition_he = String(parsed.definition_he || '').trim();
      if (!term_he || !definition_he) throw new Error('aiGlossary: missing Hebrew fields');
      return { term_he, definition_he };
    } catch (err) {
      lastErr = err;
      if (attempt >= maxRetries || !isRetryable(err)) {
        logger.warn(`[aiGlossary] translate failed for ${term.slug}: ${err.message}`);
        throw err;
      }
      const backoff = Math.min(30000, 1000 * Math.pow(2, attempt)) + Math.floor(Math.random() * 500);
      await sleep(backoff);
    }
  }
  throw lastErr || new Error('aiGlossary: unknown failure');
}

async function seedAiGlossary({ force = false } = {}) {
  const genAI = await getGenAI();
  const existing = await db.collection(COLL).get();
  const have = new Map();
  existing.forEach((d) => have.set(d.id, d.data() || {}));

  const todo = GLOSSARY_TERMS.filter((t) => {
    if (force) return true;
    const cur = have.get(t.slug);
    return !cur || !cur.term_he || !cur.definition_he;
  });

  logger.info(`[aiGlossary.seed] ${todo.length} terms to translate (force=${force})`);

  const results = await pMap(todo, async (term) => {
    const { term_he, definition_he } = await translateOne(genAI, term);
    return { term, term_he, definition_he };
  }, 4);

  const batch = db.batch();
  let written = 0;
  const failures = [];
  for (let i = 0; i < results.length; i++) {
    const r = results[i];
    if (!r) continue;
    if (!r.ok) { failures.push({ slug: todo[i].slug, error: String(r.error && r.error.message) }); continue; }
    const { term, term_he, definition_he } = r.value;
    const ref = db.collection(COLL).doc(term.slug);
    batch.set(ref, {
      slug: term.slug,
      term_en: term.term_en,
      term_he,
      definition_en: term.definition_en,
      definition_he,
      category: term.category,
      relatedTools: [],
      aliases: term.aliases || [],
      order: term.order,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, { merge: true });
    written++;
  }

  // Also upsert any terms that already had Hebrew but might need EN refresh
  // (slug + term_en + definition_en + order + category + aliases drift).
  for (const term of GLOSSARY_TERMS) {
    if (todo.find((t) => t.slug === term.slug)) continue; // already in batch above
    const ref = db.collection(COLL).doc(term.slug);
    batch.set(ref, {
      slug: term.slug,
      term_en: term.term_en,
      definition_en: term.definition_en,
      category: term.category,
      aliases: term.aliases || [],
      order: term.order,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, { merge: true });
  }

  await batch.commit();
  return { written, skipped: GLOSSARY_TERMS.length - todo.length, failures, total: GLOSSARY_TERMS.length };
}

async function getAiGlossary(/* { language = 'en' } = {} */) {
  const snap = await db.collection(COLL).get();
  const items = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
  items.sort((a, b) => {
    const ca = CATEGORY_ORDER[a.category] ?? 99;
    const cb = CATEGORY_ORDER[b.category] ?? 99;
    if (ca !== cb) return ca - cb;
    return (a.order || 0) - (b.order || 0);
  });
  return { items };
}

async function getAiGlossaryTerm(slug) {
  if (!slug || typeof slug !== 'string') throw new Error('slug required');
  const doc = await db.collection(COLL).doc(slug).get();
  if (!doc.exists) return null;
  const data = { id: doc.id, ...doc.data() };
  // Lookup related tools (max 6)
  const relatedTools = [];
  if (Array.isArray(data.relatedTools) && data.relatedTools.length) {
    const slugs = data.relatedTools.slice(0, 6);
    const fetches = await Promise.all(slugs.map((s) =>
      db.collection('ai_tools').doc(s).get().catch(() => null),
    ));
    for (const d of fetches) {
      if (d && d.exists) {
        const t = d.data();
        relatedTools.push({ slug: d.id, name: t.name, type: t.type, iconUrl: t.iconUrl || null });
      }
    }
  }
  return { ...data, relatedToolsFull: relatedTools };
}

module.exports = {
  GLOSSARY_TERMS,
  CATEGORY_ORDER,
  seedAiGlossary,
  getAiGlossary,
  getAiGlossaryTerm,
};
